+        if (savedKey === undefined) delete process.env.GOOGLE_API_KEY; else process.env.GOOGLE_API_KEY = savedKey;
+        if (savedMode !== undefined) process.env.LOA_HEADLESS_MODE = savedMode;
+      }
+    });
+  });
+});
